class ParticleSystem{constructor(){this.particleCount=25e3;this.particleVelocities=[];this.initScene();this.initCamera();this.initRenderer();this.createParticles();this.addEventListeners();this.animate()}initScene(){this.scene=new THREE.Scene;this.scene.background=new THREE.Color(0);this.scene.fog=new THREE.Fog(0,5,25)}initCamera(){const fov=75;const aspect=window.innerWidth/window.innerHeight;const near=.1;const far=1e3;this.camera=new THREE.PerspectiveCamera(fov,aspect,near,far);this.camera.position.set(0,0,5)}initRenderer(){this.renderer=new THREE.WebGLRenderer({antialias:true});this.renderer.setSize(window.innerWidth,window.innerHeight);this.renderer.setPixelRatio(window.devicePixelRatio);document.body.appendChild(this.renderer.domElement)}createParticles(){this.particlesGeometry=new THREE.BufferGeometry;const particlePositions=new Float32Array(this.particleCount*3);for(let i=0;i<this.particleCount;i++){particlePositions[i*3]=(Math.random()-.5)*30;particlePositions[i*3+1]=(Math.random()-.5)*30;particlePositions[i*3+2]=(Math.random()-.5)*30;this.particleVelocities.push({x:(Math.random()-.5)*.02,y:(Math.random()-.5)*.02,z:(Math.random()-.5)*.02})}this.particlesGeometry.setAttribute("position",new THREE.BufferAttribute(particlePositions,3));const particlesMaterial=new THREE.PointsMaterial({color:65280,size:.08,transparent:true,opacity:.8,blending:THREE.AdditiveBlending});this.particles=new THREE.Points(this.particlesGeometry,particlesMaterial);this.scene.add(this.particles)}addEventListeners(){window.addEventListener("resize",()=>this.onResize())}onResize(){this.camera.aspect=window.innerWidth/window.innerHeight;this.camera.updateProjectionMatrix();this.renderer.setSize(window.innerWidth,window.innerHeight)}updateParticles(){const positions=this.particlesGeometry.attributes.position.array;for(let i=0;i<this.particleCount;i++){positions[i*3]+=this.particleVelocities[i].x;positions[i*3+1]+=this.particleVelocities[i].y;positions[i*3+2]+=this.particleVelocities[i].z;if(Math.abs(positions[i*3])>15){positions[i*3]*=-1}if(Math.abs(positions[i*3+1])>15){positions[i*3+1]*=-1}if(Math.abs(positions[i*3+2])>15){positions[i*3+2]*=-1}}this.particlesGeometry.attributes.position.needsUpdate=true}updateCamera(){this.camera.position.x=0;this.camera.position.y=window.scrollY/(document.body.offsetHeight-window.innerHeight)*5;this.camera.lookAt(this.scene.position)}animate(){requestAnimationFrame(()=>this.animate());this.updateParticles();this.updateCamera();this.renderer.render(this.scene,this.camera)}destroy(){window.removeEventListener("resize",this.onResize);this.renderer.domElement.remove();this.particlesGeometry.dispose();this.particles.material.dispose()}}console.log("👋 Built by Justin Bull");const slider=new SnapTouch("slider");slider.create();slider.setActiveIndex(3);slider.easeTowardsTarget();const sliderElement=document.getElementById("slider");let isInteracting=false;sliderElement.addEventListener("mousedown",()=>{isInteracting=true;document.body.style.overflow="hidden"});sliderElement.addEventListener("touchstart",()=>{isInteracting=true;document.body.style.overflow="hidden"},{passive:true});window.addEventListener("mouseup",()=>{if(isInteracting){isInteracting=false;document.body.style.overflow=""}});window.addEventListener("touchend",()=>{if(isInteracting){isInteracting=false;document.body.style.overflow=""}},{passive:true});const videoTriggers=document.querySelectorAll(".video-trigger");const videoPopup=document.getElementById("videoPopup");const closeBtn=document.querySelector(".video-popup-close");const overlay=document.querySelector(".video-popup-overlay");let player;let playerReady=false;function onYouTubeIframeAPIReady(){playerReady=true}videoTriggers.forEach(trigger=>{trigger.addEventListener("click",()=>{const videoId=trigger.getAttribute("data-video-id");videoPopup.classList.add("active");if(playerReady){createPlayer(videoId)}else{setTimeout(()=>createPlayer(videoId),100)}})});function createPlayer(videoId){if(player){player.destroy()}player=new YT.Player("player",{height:"100%",width:"100%",videoId:videoId,playerVars:{autoplay:1,controls:1,modestbranding:1,rel:0},events:{onReady:onPlayerReady,onStateChange:onPlayerStateChange}})}function onPlayerReady(event){event.target.playVideo()}function onPlayerStateChange(event){const availableQualities=event.target.getAvailableQualityLevels();if(availableQualities.includes("hd1080")){event.target.setPlaybackQuality("hd1080")}}function closePopup(){videoPopup.classList.remove("active");if(player){player.stopVideo();player.destroy();player=null}}closeBtn.addEventListener("click",closePopup);overlay.addEventListener("click",closePopup);document.addEventListener("keydown",e=>{if(e.key==="Escape"&&videoPopup.classList.contains("active")){closePopup()}});AOS.init();if(window.innerWidth>1024){window.addEventListener("load",()=>{const script=document.createElement("script");script.src=window.location.origin+"/scripts/lib/three-r128.min.js";script.addEventListener("load",()=>{new ParticleSystem});document.body.appendChild(script)})}window.addEventListener("load",()=>{const loadSliderImages=()=>{document.querySelectorAll("#slider img[data-src]").forEach(img=>{img.src=img.dataset.src;img.removeAttribute("data-src")})};if("requestIdleCallback"in window){requestIdleCallback(loadSliderImages)}else{setTimeout(loadSliderImages,200)}});